create extension if not exists pgcrypto;
create type public.order_status as enum ('new','confirmed','preparing','ready','out_for_delivery','delivered','cancelled');
create type public.delivery_method as enum ('delivery','pickup');
create type public.payment_method as enum ('pix','cash','card');
create table public.admin_users (id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.restaurant_settings (id uuid primary key default gen_random_uuid(), name text not null default 'Operação Almoço', is_open boolean not null default true, delivery_fee_cents integer not null default 0 check(delivery_fee_cents >= 0), delivery_minutes_min smallint, delivery_minutes_max smallint, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, sort_order integer not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories(id), name text not null, description text, price_cents integer not null check(price_cents >= 0), image_url text, active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_daily_availability (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, date date not null, available_today boolean not null default false, sold_out boolean not null default false, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(product_id,date));
create table public.product_options (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, name text not null, required boolean not null default false, min_choices smallint not null default 0, max_choices smallint not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(max_choices >= min_choices));
create table public.product_addons (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, option_id uuid references public.product_options(id) on delete cascade, name text not null, price_cents integer not null default 0 check(price_cents >= 0), active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null, whatsapp_normalized text not null unique check(whatsapp_normalized ~ '^\\+?[0-9]{10,15}$'), internal_notes text, first_order_at timestamptz, last_order_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_addresses (id uuid primary key default gen_random_uuid(), customer_id uuid not null references public.customers(id) on delete cascade, label text, address_line text not null, complement text, neighborhood text, city text, postal_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number bigint generated always as identity unique, customer_id uuid not null references public.customers(id), status public.order_status not null default 'new', delivery_method public.delivery_method not null, payment_method public.payment_method not null, customer_name_snapshot text not null, whatsapp_snapshot text not null, address_snapshot text, change_for_cents integer check(change_for_cents is null or change_for_cents >= 0), notes text, subtotal_cents integer not null check(subtotal_cents >= 0), delivery_fee_cents integer not null default 0 check(delivery_fee_cents >= 0), total_cents integer not null check(total_cents >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name_snapshot text not null, unit_price_cents integer not null check(unit_price_cents >= 0), quantity integer not null check(quantity > 0), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_item_addons (id uuid primary key default gen_random_uuid(), order_item_id uuid not null references public.order_items(id) on delete cascade, addon_id uuid references public.product_addons(id) on delete set null, addon_name_snapshot text not null, unit_price_cents integer not null check(unit_price_cents >= 0), quantity integer not null default 1 check(quantity > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_status_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, status public.order_status not null, changed_by uuid references auth.users(id), created_at timestamptz not null default now());
create index products_category_idx on public.products(category_id); create index availability_date_idx on public.product_daily_availability(date) where available_today; create index orders_customer_idx on public.orders(customer_id); create index orders_created_idx on public.orders(created_at desc); create index status_history_order_idx on public.order_status_history(order_id,created_at);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where id=auth.uid()) $$;
create or replace function public.log_order_status() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' or new.status is distinct from old.status then insert into public.order_status_history(order_id,status,changed_by) values(new.id,new.status,auth.uid()); end if; return new; end $$;
create or replace function public.refresh_customer_stats() returns trigger language plpgsql security definer set search_path=public as $$ begin update public.customers set first_order_at=(select min(created_at) from public.orders where customer_id=new.customer_id and status <> 'cancelled'),last_order_at=(select max(created_at) from public.orders where customer_id=new.customer_id and status <> 'cancelled') where id=new.customer_id; return new; end $$;
do $$ declare t text; begin foreach t in array array['admin_users','restaurant_settings','categories','products','product_daily_availability','product_options','product_addons','customers','customer_addresses','orders','order_items','order_item_addons'] loop execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',t||'_updated',t); end loop; end $$;
create trigger order_status_audit after insert or update of status on public.orders for each row execute function public.log_order_status(); create trigger customer_order_stats after insert or update on public.orders for each row execute function public.refresh_customer_stats();
alter table public.admin_users enable row level security; alter table public.restaurant_settings enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_daily_availability enable row level security; alter table public.product_options enable row level security; alter table public.product_addons enable row level security; alter table public.customers enable row level security; alter table public.customer_addresses enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.order_item_addons enable row level security; alter table public.order_status_history enable row level security;
create policy "public menu categories" on public.categories for select using(active); create policy "public menu products" on public.products for select using(active); create policy "public daily availability" on public.product_daily_availability for select using(available_today); create policy "admin full categories" on public.categories for all using(is_admin()) with check(is_admin()); create policy "admin full products" on public.products for all using(is_admin()) with check(is_admin()); create policy "admin full availability" on public.product_daily_availability for all using(is_admin()) with check(is_admin()); create policy "admin full customers" on public.customers for all using(is_admin()) with check(is_admin()); create policy "admin full addresses" on public.customer_addresses for all using(is_admin()) with check(is_admin()); create policy "admin full orders" on public.orders for all using(is_admin()) with check(is_admin()); create policy "admin full order items" on public.order_items for all using(is_admin()) with check(is_admin()); create policy "admin full history" on public.order_status_history for select using(is_admin()); create policy "admin settings" on public.restaurant_settings for all using(is_admin()) with check(is_admin()); create policy "admin options" on public.product_options for all using(is_admin()) with check(is_admin()); create policy "admin addons" on public.product_addons for all using(is_admin()) with check(is_admin());
create or replace function public.create_order(p_customer_name text,p_whatsapp text,p_delivery_method public.delivery_method,p_payment_method public.payment_method,p_address text,p_notes text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_customer uuid; v_order uuid; v_subtotal integer:=0; v_item jsonb; v_product record; v_quantity integer; begin if jsonb_array_length(p_items)=0 then raise exception 'O pedido precisa de itens'; end if; insert into public.customers(name,whatsapp_normalized) values(trim(p_customer_name),regexp_replace(p_whatsapp,'[^0-9+]','','g')) on conflict(whatsapp_normalized) do update set name=excluded.name returning id into v_customer; for v_item in select * from jsonb_array_elements(p_items) loop v_quantity:=greatest(1,(v_item->>'quantity')::integer); select p.id,p.name,p.price_cents into v_product from public.products p join public.product_daily_availability a on a.product_id=p.id and a.date=current_date where p.id=(v_item->>'product_id')::uuid and p.active and a.available_today and not a.sold_out for share; if not found then raise exception 'Produto indisponível'; end if; v_subtotal:=v_subtotal+v_product.price_cents*v_quantity; end loop; insert into public.orders(customer_id,delivery_method,payment_method,customer_name_snapshot,whatsapp_snapshot,address_snapshot,notes,subtotal_cents,delivery_fee_cents,total_cents) values(v_customer,p_delivery_method,p_payment_method,trim(p_customer_name),p_whatsapp,p_address,p_notes,v_subtotal,case when p_delivery_method='delivery' then (select delivery_fee_cents from public.restaurant_settings limit 1) else 0 end,v_subtotal+case when p_delivery_method='delivery' then coalesce((select delivery_fee_cents from public.restaurant_settings limit 1),0) else 0 end) returning id into v_order; for v_item in select * from jsonb_array_elements(p_items) loop select p.id,p.name,p.price_cents into v_product from public.products p where p.id=(v_item->>'product_id')::uuid; insert into public.order_items(order_id,product_id,product_name_snapshot,unit_price_cents,quantity,notes) values(v_order,v_product.id,v_product.name,v_product.price_cents,greatest(1,(v_item->>'quantity')::integer),nullif(v_item->>'notes','')); end loop; return v_order; end $$;
